{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/project-grid.json
    Projects of a studio or a person: cards with tags and links, a compact grid, tiles with the caption over the picture, a bento with one big project, or a list beside a collage. Axes: layout (cards, compact, overlay, bento, list), tone, density.
    Props (p): id, title, lead, projects, labels, layout, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_projects = ($p['projects'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_8}
  {capture $c_9}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '3/4']])|noescape}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '3/4', 'className' => ui_cnv(['mt-8'])]])|noescape}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-2 gap-4', 'Attrs' => ui_attrs(['data-testid', 'collage'])], 'children' => $c_9])|noescape}
{/capture}
{capture $c_10}
  {if ui_t(ui_eq($v_layout, 'list'))}
    {capture $c_7}
      {foreach ui_l($v_projects) as $v_p}
        {capture $c_6}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_p, ['title']), 'ratio' => '1/1', 'className' => ui_cnv(['size-16 shrink-0'])]])|noescape}
          {capture $c_5}
            {capture $c_3}
              {capture $c_1}
                {=ui_text(ui_get($v_p, ['title']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
              {capture $c_2}
                {=ui_text(ui_get($v_p, ['year']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
            {/capture}
            {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Justify' => 'between'], 'children' => $c_3])|noescape}
            {capture $c_4}
              {=ui_text(ui_get($v_p, ['summary']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_4])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'stretch', 'Class' => 'flex-1'], 'children' => $c_5])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'start', 'Class' => 'border-b border-border pb-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_6])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_7])|noescape}
  {else}
    {=ui_include('blocks/project-tiles.latte', ['p' => ['projects' => $v_projects, 'labels' => $v_labels, 'layout' => $v_layout]])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'layout' => (ui_t(ui_eq($v_layout, 'list')) ? 'split' : 'stack'), 'media' => ['show' => ui_eq($v_layout, 'list'), 'align' => 'start'], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_8], 'children' => $c_10])|noescape}
